function computeMonthlyCost(
  requests: number,
  avgInputTokens: number,
  avgOutputTokens: number,
  inputPer1MUsd: number,
  outputPer1MUsd: number
) {
  const inputCostUsd = requests * avgInputTokens * (inputPer1MUsd / 1_000_000);
  const outputCostUsd = requests * avgOutputTokens * (outputPer1MUsd / 1_000_000);
  const totalUsd = inputCostUsd + outputCostUsd;
  return { inputCostUsd, outputCostUsd, totalUsd, outputSharePct: (outputCostUsd / totalUsd) * 100 };
}

